CREATE OR REPLACE FUNCTION public.assign_human_handoff(p_lead_id uuid, p_reason text, p_category text DEFAULT 'operator_takeover'::text, p_target_user_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_organization_id uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
  v_target_user_id uuid := coalesce(p_target_user_id, auth.uid());
  v_target_name text;
  v_actor_name text := 'Usuário';
  v_lead public.leads%rowtype;
  v_target_account public.whatsapp_accounts%rowtype;
  v_handoff_id uuid;
  v_cancelled_jobs integer := 0;
  v_reused boolean := false;
  v_now timestamptz := now();
begin
  if v_user_id is null or v_organization_id is null
     or not private.is_active_org_member(v_organization_id, v_user_id) then
    raise exception 'organization_context_required';
  end if;
  if p_lead_id is null or nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'lead_and_reason_required';
  end if;
  if nullif(btrim(coalesce(p_category, '')), '') not in ('operator_takeover', 'operator_transfer') then
    raise exception 'invalid_handoff_category';
  end if;

  select lead.* into v_lead
    from public.leads as lead
   where lead.id = p_lead_id
     and lead.organization_id = v_organization_id
     and (
       private.has_org_role(v_organization_id, v_user_id, array[
         'administrador'::public.app_role,
         'sdr'::public.app_role,
         'ia'::public.app_role,
         'cx'::public.app_role
       ])
       or lead.owner_id = v_user_id
       or lead.assigned_to = v_user_id
     )
   for update;
  if not found then raise exception 'lead_not_found_or_access_denied'; end if;

  select profile.name into v_target_name
    from public.organization_members as member
    join public.profiles as profile on profile.id = member.user_id
   where member.organization_id = v_organization_id
     and member.user_id = v_target_user_id
     and member.status = 'active'
   limit 1;
  if v_target_name is null then raise exception 'handoff_assignee_inactive'; end if;
  if not private.has_org_permission(v_organization_id, v_target_user_id, 'conversations.reply_all')
     and not private.has_org_permission(v_organization_id, v_target_user_id, 'conversations.reply_assigned') then
    raise exception 'handoff_assignee_cannot_reply';
  end if;

  select account.* into v_target_account
    from public.whatsapp_accounts as account
   where account.organization_id = v_organization_id
     and account.owner_user_id = v_target_user_id
     and account.account_type = 'seller'
     and account.archived_at is null
   order by account.updated_at desc
   limit 1
   for update;
  if not found then raise exception 'handoff_target_whatsapp_account_required'; end if;
  if not v_target_account.enabled or v_target_account.connection_status <> 'connected' then
    raise exception 'handoff_target_whatsapp_account_not_ready';
  end if;
  if not exists (
    select 1
      from public.integrations as integration
     where integration.id = v_target_account.integration_id
       and integration.organization_id = v_organization_id
       and integration.enabled
       and integration.connected
       and not integration.paused
  ) then
    raise exception 'handoff_target_whatsapp_integration_not_ready';
  end if;
  if not exists (
    select 1
      from public.messaging_provider_controls as control
     where control.organization_id = v_organization_id
       and control.provider = v_target_account.provider
       and control.send_enabled
       and not control.kill_switch
  ) then
    raise exception 'handoff_target_whatsapp_provider_not_ready';
  end if;

  select coalesce(nullif(btrim(profile.name), ''), 'Usuário')
    into v_actor_name
    from public.profiles as profile
   where profile.id = v_user_id;

  update public.leads as lead
     set modo_atendimento = 'humano',
         ai_paused = true,
         automation_status = 'human',
         automation_error = null,
         automation_updated_at = v_now,
         no_reply_deadline_at = null,
         assigned_to = v_target_user_id,
         owner_id = v_target_user_id,
         owner = left(coalesce(nullif(btrim(v_target_name), ''), 'Responsável'), 160),
         whatsapp_account_id = v_target_account.id,
         active_channel = 'whatsapp',
         updated_at = v_now
   where lead.id = p_lead_id
     and lead.organization_id = v_organization_id;

  update public.outreach_jobs as job
     set status = 'cancelled', processed_at = v_now, locked_at = null, locked_by = null,
         error = 'cancelled_by_human_handoff'
   where job.organization_id = v_organization_id
     and job.lead_id = p_lead_id
     and job.status in ('queued', 'retry', 'reconciliation_required')
     and job.processed_at is null
     and job.locked_at is null
     and job.locked_by is null
     and lower(coalesce(job.payload ->> 'manual', 'false')) <> 'true'
     and not coalesce(job.payload ? 'provider_message_id', false)
     and not exists (
       select 1
         from public.lead_outreach as outreach
        where outreach.id = job.id
          and outreach.organization_id = job.organization_id
          and (
            outreach.provider_message_id is not null
            or outreach.status in ('sent', 'delivered', 'read', 'replied', 'failed')
          )
     );
  get diagnostics v_cancelled_jobs = row_count;

  select handoff.id into v_handoff_id
    from public.lead_handoffs as handoff
   where handoff.organization_id = v_organization_id
     and handoff.lead_id = p_lead_id
     and handoff.status in ('pending', 'accepted')
   order by handoff.requested_at desc, handoff.created_at desc
   limit 1
   for update;

  if v_handoff_id is null then
    insert into public.lead_handoffs (
      organization_id, lead_id, from_user_id, to_user_id, assigned_to, status,
      requested_at, reason, category, summary, context, updated_at
    ) values (
      v_organization_id, p_lead_id, v_user_id, v_target_user_id, v_target_user_id,
      'pending', v_now, left(btrim(p_reason), 1000), left(p_category, 120),
      left(btrim(p_reason), 1000),
      jsonb_build_object(
        'source', 'central_atendimento',
        'actor_id', v_user_id,
        'cancelled_automatic_jobs', v_cancelled_jobs,
        'previous_whatsapp_account_id', v_lead.whatsapp_account_id,
        'whatsapp_account_id', v_target_account.id
      ),
      v_now
    ) returning id into v_handoff_id;
  else
    v_reused := true;
    update public.lead_handoffs as handoff
       set to_user_id = v_target_user_id,
           assigned_to = v_target_user_id,
           reason = left(btrim(p_reason), 1000),
           category = left(p_category, 120),
           context = coalesce(handoff.context, '{}'::jsonb) || jsonb_build_object(
             'last_request_at', v_now,
             'last_actor_id', v_user_id,
             'cancelled_automatic_jobs', v_cancelled_jobs,
             'previous_whatsapp_account_id', v_lead.whatsapp_account_id,
             'whatsapp_account_id', v_target_account.id
           ),
           updated_at = v_now
     where handoff.id = v_handoff_id
       and handoff.organization_id = v_organization_id;
  end if;

  if v_lead.whatsapp_account_id is distinct from v_target_account.id then
    if v_lead.whatsapp_account_id is not null and not exists (
      select 1
        from public.lead_whatsapp_account_bindings as binding
       where binding.organization_id = v_organization_id
         and binding.lead_id = p_lead_id
         and binding.unbound_at is null
    ) then
      insert into public.lead_whatsapp_account_bindings (
        organization_id, lead_id, whatsapp_account_id, bound_by,
        reason, bound_at
      ) values (
        v_organization_id, p_lead_id, v_lead.whatsapp_account_id, v_user_id,
        'reconstructed_before_handoff', coalesce(v_lead.updated_at, v_now)
      );
    end if;

    update public.lead_whatsapp_account_bindings as binding
       set unbound_at = v_now
     where binding.organization_id = v_organization_id
       and binding.lead_id = p_lead_id
       and binding.unbound_at is null;

    insert into public.lead_whatsapp_account_bindings (
      organization_id, lead_id, whatsapp_account_id, handoff_id,
      bound_by, reason, bound_at
    ) values (
      v_organization_id, p_lead_id, v_target_account.id, v_handoff_id,
      v_user_id, p_category, v_now
    );
  elsif not exists (
    select 1
      from public.lead_whatsapp_account_bindings as binding
     where binding.organization_id = v_organization_id
       and binding.lead_id = p_lead_id
       and binding.unbound_at is null
  ) then
    insert into public.lead_whatsapp_account_bindings (
      organization_id, lead_id, whatsapp_account_id, handoff_id,
      bound_by, reason, bound_at
    ) values (
      v_organization_id, p_lead_id, v_target_account.id, v_handoff_id,
      v_user_id, p_category, v_now
    );
  end if;

  insert into public.audit_logs (
    organization_id, actor_id, actor_name, actor_type, action, detail,
    entity_table, entity_id, event_data
  ) values (
    v_organization_id, v_user_id, coalesce(v_actor_name, 'Usuário'), 'user',
    case when p_category = 'operator_takeover'
      then 'lead.handoff.taken_over'
      else 'lead.handoff.transferred'
    end,
    case when p_category = 'operator_takeover'
      then 'Atendimento assumido com o canal privado do operador.'
      else 'Atendimento e canal de saída transferidos para o responsável selecionado.'
    end,
    'leads', p_lead_id,
    jsonb_build_object(
      'handoff_id', v_handoff_id,
      'target_user_id', v_target_user_id,
      'category', p_category,
      'reused', v_reused,
      'cancelled_automatic_jobs', v_cancelled_jobs,
      'previous_whatsapp_account_id', v_lead.whatsapp_account_id,
      'whatsapp_account_id', v_target_account.id,
      'provider', v_target_account.provider,
      'phone_suffix', v_target_account.connected_phone_suffix
    )
  );

  return v_handoff_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.configure_lead_handoff_policy(p_lead_ids uuid[], p_assignee_user_id uuid DEFAULT NULL::uuid, p_handoff_stage text DEFAULT NULL::text, p_notify_whatsapp boolean DEFAULT false)
 RETURNS TABLE(lead_id uuid, assignee_user_id uuid, handoff_stage text, notify_whatsapp boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_organization_id uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
  v_stage text := nullif(lower(trim(coalesce(p_handoff_stage, ''))), '');
  v_assignee_name text;
  v_expected integer;
begin
  if v_organization_id is null or v_user_id is null
     or not private.is_active_org_member(v_organization_id, v_user_id) then
    raise exception 'organization_context_required';
  end if;
  if p_lead_ids is null or cardinality(p_lead_ids) is null or cardinality(p_lead_ids) = 0
     or cardinality(p_lead_ids) > 100 then
    raise exception 'lead_selection_required';
  end if;
  if cardinality(array(select distinct value from unnest(p_lead_ids) as value)) <> cardinality(p_lead_ids) then
    raise exception 'duplicate_lead_selection';
  end if;

  v_expected := cardinality(p_lead_ids);
  if (select count(*) from public.leads lead
      where lead.organization_id = v_organization_id
        and lead.id = any(p_lead_ids)
        and private.can_manage_lead(v_organization_id, lead.id, v_user_id)) <> v_expected then
    raise exception 'lead_not_found_or_access_denied';
  end if;

  if v_stage is null then
    if p_assignee_user_id is not null then raise exception 'handoff_stage_required'; end if;
    delete from public.lead_handoff_policies
      where organization_id = v_organization_id and lead_id = any(p_lead_ids);
    return;
  end if;
  if v_stage not in ('novo','apresentado','qualificando','reuniao','orcamento') then
    raise exception 'invalid_handoff_stage';
  end if;
  if p_assignee_user_id is null then raise exception 'handoff_assignee_required'; end if;

  select profile.name into v_assignee_name
    from public.organization_members member
    join public.profiles profile on profile.id = member.user_id
   where member.organization_id = v_organization_id
     and member.user_id = p_assignee_user_id
     and member.status = 'active'
   limit 1;
  if v_assignee_name is null then raise exception 'handoff_assignee_inactive'; end if;
  if not private.has_org_permission(v_organization_id, p_assignee_user_id, 'conversations.reply_all')
     and not private.has_org_permission(v_organization_id, p_assignee_user_id, 'conversations.reply_assigned') then
    raise exception 'handoff_assignee_cannot_reply';
  end if;
  if p_notify_whatsapp and not exists (
    select 1 from public.notification_preferences preference
     where preference.organization_id = v_organization_id
       and preference.user_id = p_assignee_user_id
       and preference.handoff_whatsapp_enabled = true
       and preference.handoff_whatsapp_phone ~ '^[1-9][0-9]{7,14}$'
  ) then
    raise exception 'handoff_whatsapp_not_configured';
  end if;

  insert into public.lead_handoff_policies (
    organization_id, lead_id, assignee_user_id, handoff_stage, notify_whatsapp, created_by, updated_at
  )
  select v_organization_id, item.lead_id, p_assignee_user_id, v_stage, p_notify_whatsapp, v_user_id, now()
    from unnest(p_lead_ids) as item(lead_id)
  on conflict (organization_id, lead_id) do update set
    assignee_user_id = excluded.assignee_user_id,
    handoff_stage = excluded.handoff_stage,
    notify_whatsapp = excluded.notify_whatsapp,
    created_by = excluded.created_by,
    updated_at = now();

  update public.leads
     set owner_id = p_assignee_user_id,
         assigned_to = p_assignee_user_id,
         owner = left(coalesce(nullif(trim(v_assignee_name), ''), 'Responsável'), 160),
         updated_at = now()
   where organization_id = v_organization_id and id = any(p_lead_ids);

  insert into public.audit_logs (
    organization_id, actor_id, actor_name, actor_type, action, detail, entity_table, entity_id, event_data
  )
  select v_organization_id, v_user_id, coalesce(profile.name, 'Usuário'), 'user',
    'lead.handoff_policy.configured', 'Responsável e etapa de transferência automática configurados.',
    'leads', item.lead_id,
    jsonb_build_object('assignee_user_id', p_assignee_user_id, 'handoff_stage', v_stage, 'notify_whatsapp', p_notify_whatsapp)
  from unnest(p_lead_ids) as item(lead_id)
  left join public.profiles profile on profile.id = v_user_id;

  return query
    select policy.lead_id, policy.assignee_user_id, policy.handoff_stage, policy.notify_whatsapp
      from public.lead_handoff_policies policy
     where policy.organization_id = v_organization_id and policy.lead_id = any(p_lead_ids);
end;
$function$

CREATE OR REPLACE FUNCTION public.request_human_handoff(p_lead_id uuid, p_reason text, p_category text DEFAULT 'operator_request'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_organization_id uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
  v_actor_name text := 'Usuário';
  v_lead public.leads%rowtype;
  v_handoff_id uuid;
  v_assignee uuid;
  v_cancelled_jobs integer := 0;
  v_reused boolean := false;
  v_now timestamptz := pg_catalog.now();
begin
  if v_user_id is null or v_organization_id is null
     or not private.is_active_org_member(v_organization_id, v_user_id) then
    raise exception 'organization_context_required';
  end if;
  if p_lead_id is null or nullif(pg_catalog.btrim(p_reason), '') is null then
    raise exception 'lead_and_reason_required';
  end if;

  select l.* into v_lead
    from public.leads as l
   where l.id = p_lead_id
     and l.organization_id = v_organization_id
     and (
       private.has_org_role(
         v_organization_id,
         v_user_id,
         array[
           'administrador'::public.app_role,
           'sdr'::public.app_role,
           'ia'::public.app_role,
           'cx'::public.app_role
         ]
       )
       or l.owner_id = v_user_id
       or l.assigned_to = v_user_id
     )
   for update;
  if not found then raise exception 'lead_not_found_or_access_denied'; end if;

  select coalesce(nullif(pg_catalog.btrim(p.name), ''), 'Usuário')
    into v_actor_name from public.profiles as p where p.id = v_user_id;
  v_assignee := coalesce(v_lead.assigned_to, v_lead.owner_id, v_user_id);

  update public.leads
     set modo_atendimento = 'humano',
         ai_paused = true,
         automation_status = 'human',
         automation_error = null,
         automation_updated_at = v_now,
         no_reply_deadline_at = null,
         updated_at = v_now
   where id = p_lead_id and organization_id = v_organization_id;

  update public.outreach_jobs as j
     set status = 'cancelled', processed_at = v_now, locked_at = null, locked_by = null,
         error = 'cancelled_by_human_handoff'
   where j.organization_id = v_organization_id
     and j.lead_id = p_lead_id
     and j.status in ('queued', 'retry', 'reconciliation_required')
     and j.processed_at is null and j.locked_at is null and j.locked_by is null
     and pg_catalog.lower(coalesce(j.payload ->> 'manual', 'false')) <> 'true'
     and not coalesce(j.payload ? 'provider_message_id', false)
     and not exists (
       select 1 from public.lead_outreach as o
        where o.id = j.id
          and o.organization_id = j.organization_id
          and (
            o.provider_message_id is not null
            or o.status in ('sent', 'delivered', 'read', 'replied', 'failed')
          )
     );
  get diagnostics v_cancelled_jobs = row_count;

  select h.id into v_handoff_id
    from public.lead_handoffs as h
   where h.organization_id = v_organization_id
     and h.lead_id = p_lead_id
     and h.status in ('pending', 'accepted')
   order by h.requested_at desc, h.created_at desc
   limit 1 for update;

  if v_handoff_id is null then
    insert into public.lead_handoffs (
      organization_id, lead_id, from_user_id, to_user_id, assigned_to, status,
      requested_at, reason, category, summary, context, updated_at
    ) values (
      v_organization_id, p_lead_id, v_user_id, v_assignee, v_assignee, 'pending', v_now,
      pg_catalog.left(pg_catalog.btrim(p_reason), 1000),
      pg_catalog.left(coalesce(nullif(pg_catalog.btrim(p_category), ''), 'operator_request'), 120),
      pg_catalog.left(pg_catalog.btrim(p_reason), 1000),
      pg_catalog.jsonb_build_object('source', 'central_atendimento', 'actor_id', v_user_id, 'cancelled_automatic_jobs', v_cancelled_jobs),
      v_now
    ) returning id into v_handoff_id;
  else
    v_reused := true;
    update public.lead_handoffs as h
       set to_user_id = coalesce(h.to_user_id, v_assignee),
           assigned_to = coalesce(h.assigned_to, v_assignee),
           context = coalesce(h.context, '{}'::jsonb)
             || pg_catalog.jsonb_build_object('last_request_at', v_now, 'last_actor_id', v_user_id, 'cancelled_automatic_jobs', v_cancelled_jobs),
           updated_at = v_now
     where h.id = v_handoff_id and h.organization_id = v_organization_id;
  end if;

  insert into public.audit_logs (
    organization_id, actor_id, actor_name, actor_type, action, detail,
    entity_table, entity_id, event_data
  ) values (
    v_organization_id, v_user_id, coalesce(v_actor_name, 'Usuário'), 'user',
    'lead.handoff.requested', 'Atendimento transferido para uma pessoa.', 'leads', p_lead_id,
    pg_catalog.jsonb_build_object(
      'handoff_id', v_handoff_id,
      'category', coalesce(nullif(pg_catalog.btrim(p_category), ''), 'operator_request'),
      'reused', v_reused,
      'cancelled_automatic_jobs', v_cancelled_jobs
    )
  );
  return v_handoff_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.return_handoff_to_ana(p_lead_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_organization_id uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
  v_actor_name text := 'Usuário';
  v_lead public.leads%rowtype;
  v_cancelled_jobs integer := 0;
  v_now timestamptz := pg_catalog.now();
begin
  if v_user_id is null or v_organization_id is null
     or not private.is_active_org_member(v_organization_id, v_user_id) then
    raise exception 'organization_context_required';
  end if;

  select l.* into v_lead
    from public.leads as l
   where l.id = p_lead_id
     and l.organization_id = v_organization_id
     and (
       private.has_org_role(
         v_organization_id,
         v_user_id,
         array[
           'administrador'::public.app_role,
           'sdr'::public.app_role,
           'ia'::public.app_role,
           'cx'::public.app_role
         ]
       )
       or l.owner_id = v_user_id
       or l.assigned_to = v_user_id
     )
   for update;
  if not found then raise exception 'lead_not_found_or_access_denied'; end if;
  if coalesce(v_lead.opt_out, false) then raise exception 'lead_opt_out'; end if;
  if v_lead.contact_approval_status is distinct from 'approved'
     or v_lead.contact_approved_at is null then
    raise exception 'contact_approval_required';
  end if;

  select coalesce(nullif(pg_catalog.btrim(p.name), ''), 'Usuário')
    into v_actor_name from public.profiles as p where p.id = v_user_id;

  update public.outreach_jobs as j
     set status = 'cancelled', processed_at = v_now, locked_at = null, locked_by = null,
         error = 'cancelled_before_return_to_ana'
   where j.organization_id = v_organization_id
     and j.lead_id = p_lead_id
     and j.status in ('queued', 'retry', 'reconciliation_required')
     and j.processed_at is null and j.locked_at is null and j.locked_by is null
     and pg_catalog.lower(coalesce(j.payload ->> 'manual', 'false')) <> 'true'
     and not coalesce(j.payload ? 'provider_message_id', false)
     and not exists (
       select 1 from public.lead_outreach as o
        where o.id = j.id
          and o.organization_id = j.organization_id
          and (
            o.provider_message_id is not null
            or o.status in ('sent', 'delivered', 'read', 'replied', 'failed')
          )
     );
  get diagnostics v_cancelled_jobs = row_count;

  update public.leads
     set modo_atendimento = 'ia',
         ai_paused = false,
         automation_status = 'running',
         automation_error = null,
         automation_updated_at = v_now,
         no_reply_deadline_at = null,
         no_reply_processed_at = null,
         updated_at = v_now
   where id = p_lead_id and organization_id = v_organization_id;

  update public.lead_handoffs
     set status = 'closed', closed_at = v_now, updated_at = v_now
   where organization_id = v_organization_id
     and lead_id = p_lead_id
     and status in ('pending', 'accepted');

  insert into public.audit_logs (
